export default function () {
    class ToastMessageManager extends HTMLElement {
        constructor() {
            super();
        }

        pushMessage(content, type) {
            var toast = document.createElement('toast-message');
            toast.setContent(content, type);
            this.appendChild(toast);
            setTimeout(() => {
                toast.classList.add('open');
            }, 300);
        }
    }

    customElements.define('toast-message-manager', ToastMessageManager);

    class ToastMessage extends HTMLElement {
        constructor() {
            super();
            this.waitToCloseTimeout = setTimeout(() => {
                this.close();
            }, 4300);
        }

        connectedCallback() {
            this.appendCloseButton();
        }

        renderIcon(type) {
            switch (type) {
              case "success":
                return `<svg class="toast-icon" width="24px" height="24px" viewBox="0 0 24 24" version="1.1" xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink">
                    <title>Icon/Fill/Check-Circle-Fill备份</title>
                    <g id="商详页" stroke="none" stroke-width="1" fill="none" fill-rule="evenodd">
                        <g id="画板" transform="translate(-156.000000, -111.000000)" fill="#52C41A">
                            <g id="Icon/Fill/Check-Circle-Fill备份" transform="translate(156.000000, 111.000000)">
                                <path d="M12,0 C5.37321429,0 0,5.37321429 0,12 C0,18.6267857 5.37321429,24 12,24 C18.6267857,24 24,18.6267857 24,12 C24,5.37321429 18.6267857,0 12,0 Z M17.2637321,8.22589286 L11.6226607,16.0473214 C11.2824821,16.5214286 10.5780178,16.5214286 10.2378393,16.0473214 L6.89766068,11.41875 C6.79587497,11.2767857 6.89766068,11.0785714 7.07176782,11.0785714 L8.32801782,11.0785714 C8.60123211,11.0785714 8.86105354,11.2098214 9.02176782,11.4348214 L10.9289107,14.08125 L15.139625,8.24196429 C15.3003393,8.01964286 15.5574821,7.88571429 15.833375,7.88571429 L17.089625,7.88571429 C17.2637321,7.88571429 17.3655178,8.08392857 17.2637321,8.22589286 Z" id="形状"></path>
                            </g>
                        </g>
                    </g>
                </svg>`
                break;
              case "error":
                return `<svg class="toast-icon" width="24px" height="24px" viewBox="0 0 24 24" version="1.1" xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink">
                    <title>形状</title>
                    <g id="商详页" stroke="none" stroke-width="1" fill="none" fill-rule="evenodd">
                        <g id="画板" transform="translate(-129.000000, -199.000000)" fill="#FF4D4F">
                            <path d="M141,199 C134.373214,199 129,204.373214 129,211 C129,217.626786 134.373214,223 141,223 C147.626786,223 153,217.626786 153,211 C153,204.373214 147.626786,199 141,199 Z M140.142857,205.214286 C140.142857,205.096429 140.239286,205 140.357143,205 L141.642857,205 C141.760714,205 141.857143,205.096429 141.857143,205.214286 L141.857143,212.5 C141.857143,212.617857 141.760714,212.714286 141.642857,212.714286 L140.357143,212.714286 C140.239286,212.714286 140.142857,212.617857 140.142857,212.5 L140.142857,205.214286 Z M141,217 C140.290179,217 139.714286,216.424107 139.714286,215.714286 C139.714286,215.004464 140.290179,214.428571 141,214.428571 C141.709821,214.428571 142.285714,215.004464 142.285714,215.714286 C142.285714,216.424107 141.709821,217 141,217 Z" id="形状"></path>
                        </g>
                    </g>
                </svg>`
                break;
              default:
                return `<svg class="toast-icon" width="24px" height="24px" viewBox="0 0 24 24" version="1.1" xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink">
                    <title>形状</title>
                    <g id="商详页" stroke="none" stroke-width="1" fill="none" fill-rule="evenodd">
                        <g id="画板" transform="translate(-129.000000, -199.000000)" fill="#FF4D4F">
                            <path d="M141,199 C134.373214,199 129,204.373214 129,211 C129,217.626786 134.373214,223 141,223 C147.626786,223 153,217.626786 153,211 C153,204.373214 147.626786,199 141,199 Z M140.142857,205.214286 C140.142857,205.096429 140.239286,205 140.357143,205 L141.642857,205 C141.760714,205 141.857143,205.096429 141.857143,205.214286 L141.857143,212.5 C141.857143,212.617857 141.760714,212.714286 141.642857,212.714286 L140.357143,212.714286 C140.239286,212.714286 140.142857,212.617857 140.142857,212.5 L140.142857,205.214286 Z M141,217 C140.290179,217 139.714286,216.424107 139.714286,215.714286 C139.714286,215.004464 140.290179,214.428571 141,214.428571 C141.709821,214.428571 142.285714,215.004464 142.285714,215.714286 C142.285714,216.424107 141.709821,217 141,217 Z" id="形状"></path>
                        </g>
                    </g>
                </svg>`
                break;
            }
          }

        setContent(str, type) {
            this.appendChild(document.createElement('div'));
            this.contentWrapper = this.querySelector('div');
            this.contentWrapper.classList.add('alert');
            this.contentWrapper.textContent = str;
            this.contentWrapper.classList.add(`alert--${type}`);

            $(this.contentWrapper).prepend($(this.renderIcon(type)))
        }

        close() {
            this.classList.remove('open');
            setTimeout(() => {
                this.remove();
            }, 300);
        }

        appendCloseButton() {
            const button = document.createElement('button');
            button.setAttribute('type', 'button');
            button.classList.add('toast__button', 'color-foreground');
            const icon = `<svg xmlns="http://www.w3.org/2000/svg" aria-hidden="true" focusable="false" role="presentation"
            class="icon icon-close icon-close-sample" width="24" height="24" viewBox="0 0 22 22" fill="none">
            <path d="M5.5 16.5L16.5 5.5M5.5 5.5L16.5 16.5" stroke="currentColor" stroke-width="2" stroke-linecap="round"
              stroke-linejoin="round"></path>
            </svg>`;
            $(button).append(icon);
            this.onButtonClickHandler = this.onButtonClick.bind(this);
            button.addEventListener('click', this.onButtonClickHandler);
            this.contentWrapper.appendChild(button);
        }

        onButtonClick() {
            if (this.waitToCloseTimeout) {
                clearTimeout(this.waitToCloseTimeout);
            }
            this.close();
        }
    }

    customElements.define('toast-message', ToastMessage);
}